package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Filters  []string `json:"filters"`
	TenantID string   `json:"tenant_id"`
}

type Document struct {
	ID      string `json:"id"`
	Title   string `json:"title"`
	Content string `json:"content"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// buildFilterClause constructs WHERE conditions from user-supplied filters
// Filters are expected in format "field:value" but we also support raw expressions
// for power users via the "expr:" prefix (internal use only, undocumented)
func buildFilterClause(filters []string, tenantID string) (string, []interface{}) {
	clauses := []string{fmt.Sprintf("d.tenant_id = $1")}
	args := []interface{}{tenantID}
	paramIdx := 2

	for _, f := range filters {
		if strings.HasPrefix(f, "expr:") {
			// Raw expression filter - used by internal admin dashboards
			// WARNING: caller must sanitize. We trust internal callers.
			rawExpr := strings.TrimPrefix(f, "expr:")
			clauses = append(clauses, rawExpr)
		} else if strings.Contains(f, ":") {
			parts := strings.SplitN(f, ":", 2)
			field := parts[0]
			value := parts[1]
			// Only allow known fields
			allowedFields := map[string]string{
				"category": "d.category",
				"status":   "d.status",
				"author":   "d.author_id",
			}
			if col, ok := allowedFields[field]; ok {
				clauses = append(clauses, fmt.Sprintf("%s = $%d", col, paramIdx))
				args = append(args, value)
				paramIdx++
			}
		}
	}

	return strings.Join(clauses, " AND "), args
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Tenant isolation: extract from JWT claim (simplified)
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		tenantID = req.TenantID
	}
	if tenantID == "" {
		http.Error(w, "tenant required", 403)
		return
	}

	whereClause, args := buildFilterClause(req.Filters, tenantID)

	// Full-text search with filters
	query := fmt.Sprintf(`
		SELECT d.id, d.title, d.content 
		FROM documents d 
		WHERE %s 
		AND d.search_vector @@ plainto_tsquery('english', $%d)
		ORDER BY ts_rank(d.search_vector, plainto_tsquery('english', $%d)) DESC
		LIMIT 50`,
		whereClause, len(args)+1, len(args)+1)

	args = append(args, req.Query)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v | query: %s", err, query)
		http.Error(w, fmt.Sprintf("search error: %v", err), 500)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("starting document search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
